package com.oms.supplychain.service.wms;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.test.util.ReflectionTestUtils;
import com.oms.common.api.RemoteInventoryService;
import com.oms.common.model.dto.wms.WmsInventoryBatchDto;
import com.ruoyi.common.core.domain.R;
import org.mockito.ArgumentCaptor;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
class ExchangeReturnTest {
    private static com.alibaba.druid.pool.DruidDataSource pool;
    static { Runtime.getRuntime().addShutdownHook(new Thread(()->{if(pool!=null)pool.close();})); }
    private static synchronized javax.sql.DataSource database(String url){
        if(url==null||!url.contains("/purchase_workspace_test?"))throw new IllegalArgumentException("Disposable schema required");
        if(pool==null){pool=new com.alibaba.druid.pool.DruidDataSource();pool.setUrl(url);pool.setUsername("root");pool.setPassword(System.getenv("INVENTORY_TEST_PASSWORD"));pool.setMaxActive(8);pool.setMaxWait(10000);}
        return pool;
    }
    JdbcTemplate jdbc;WmsStore db;ExchangeReturnService service;RemoteInventoryService inventory;Map<String,Object> task;QimenReturnProtocol protocol=new QimenReturnProtocol();
    @BeforeEach void setup(){String url=System.getenv("PURCHASE_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/purchase_workspace_test?"));javax.sql.DataSource ds=database(url);jdbc=new JdbcTemplate(ds);db=new WmsStore();db.jdbc=jdbc;ReflectionTestUtils.setField(db,"transactionManager",new DataSourceTransactionManager(ds));for(String table:Arrays.asList("wms_exchange_return_review","wms_exchange_return_line","wms_exchange_return_event","wms_exchange_return"))jdbc.update("DELETE FROM "+table);inventory=mock(RemoteInventoryService.class);when(inventory.addInventory(any(),anyString())).thenReturn(R.ok(true));service=new ExchangeReturnService();ReflectionTestUtils.setField(service,"db",db);ReflectionTestUtils.setField(service,"inventory",inventory);ReflectionTestUtils.setField(service,"logs",mock(WmsInteractionLog.class));long id=db.insert("wms_exchange_return",map("company_code","QM","exchange_id",1,"return_sn","THX_TEST","exchange_sn","HH_TEST","order_sn","SO_TEST","platform_tid","123456","original_shipment_sn","XS_TEST","store_code","V1","sku_sn","A","quantity",5,"unit_cost","2.50","connection_id",1,"external_warehouse","EXT-W","external_owner","EXT-O","real_store_code","W","owner_code","O","payload_hash","hash"));task=db.one("SELECT * FROM wms_exchange_return WHERE id=?",id);}
    WmsProtocol.Receipt receipt(String message,int quantity,boolean complete){WmsProtocol.Receipt r=new WmsProtocol.Receipt();r.messageId=message;r.ticketSn="THX_TEST";r.externalOrder="WH_RETURN";r.warehouse="EXT-W";r.owner="EXT-O";r.complete=complete;r.status=complete?"FULFILLED":"PARTFULFILLED";WmsProtocol.Line line=new WmsProtocol.Line();line.sku="A";line.owner="EXT-O";line.batch="RET-BATCH";line.good=quantity;r.lines.add(line);return r;}
    void post(){ReflectionTestUtils.invokeMethod(service,"post","QM",1L);}
    @Test void receiptIsDurableBeforePostingAndDuplicateDoesNotCreateLines(){WmsProtocol.Receipt r=receipt("M1",5,true);service.accept("QM",task,r,0);verifyNoInteractions(inventory);service.accept("QM",task,r,0);assertEquals(1L,jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return_line",Long.class));assertEquals(5L,jdbc.queryForObject("SELECT accepted_quantity FROM wms_exchange_return",Long.class));}
    @Test void conflictingMessageIsRejectedWithoutAdditionalStock(){service.accept("QM",task,receipt("M1",2,false),0);assertThrows(IllegalArgumentException.class,()->service.accept("QM",task,receipt("M1",3,false),0));assertEquals(2L,jdbc.queryForObject("SELECT accepted_quantity FROM wms_exchange_return",Long.class));verifyNoInteractions(inventory);}
    @Test void wrongWarehouseCannotAddReturnStock(){WmsProtocol.Receipt r=receipt("M1",5,true);r.warehouse="OTHER";assertThrows(IllegalArgumentException.class,()->service.accept("QM",task,r,0));assertEquals(0L,jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return_event",Long.class));}
    @Test void wrongSkuCannotAddReturnStock(){WmsProtocol.Receipt r=receipt("M1",5,true);r.lines.get(0).sku="B";assertThrows(IllegalArgumentException.class,()->service.accept("QM",task,r,0));verifyNoInteractions(inventory);}
    @Test void excessOrFinalShortQuantityIsRejected(){assertThrows(IllegalArgumentException.class,()->service.accept("QM",task,receipt("M1",6,true),0));assertThrows(IllegalArgumentException.class,()->service.accept("QM",task,receipt("M2",4,true),0));assertEquals(0L,jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return_event",Long.class));}
    @Test void actualReceiptIsPostedOnceUsingTheOriginalCost(){service.accept("QM",task,receipt("M1",5,true),0);post();post();ArgumentCaptor<WmsInventoryBatchDto> capture=ArgumentCaptor.forClass(WmsInventoryBatchDto.class);verify(inventory,times(1)).addInventory(capture.capture(),eq("QM"));WmsInventoryBatchDto dto=capture.getValue();assertTrue(dto.getRelationSn().startsWith("EXCHANGE_RETURN_"));assertEquals(5,dto.getWmsInventoryBatch().getZpActualNumber());assertEquals(0,new java.math.BigDecimal("2.50").compareTo(dto.getWmsInventoryBatch().getTransactionPrice()));assertEquals("COMPLETED",service.detail("QM",1).get("receipt_state"));}
    @Test void failedPostingKeepsStableKeyForRetry(){service.accept("QM",task,receipt("M1",5,true),0);when(inventory.addInventory(any(),anyString())).thenReturn(R.fail("unavailable"));post();assertEquals(0L,jdbc.queryForObject("SELECT posted FROM wms_exchange_return_line",Long.class));when(inventory.addInventory(any(),anyString())).thenReturn(R.ok(true));post();ArgumentCaptor<WmsInventoryBatchDto> c=ArgumentCaptor.forClass(WmsInventoryBatchDto.class);verify(inventory,times(2)).addInventory(c.capture(),eq("QM"));assertEquals(c.getAllValues().get(0).getRelationSn(),c.getAllValues().get(1).getRelationSn());assertEquals(5L,jdbc.queryForObject("SELECT posted_quantity FROM wms_exchange_return",Long.class));}
    @Test void badGoodsArePostedAsBadStockAndNotGoodAvailableStock(){WmsProtocol.Receipt r=receipt("M1",0,true);r.lines.get(0).bad=5;service.accept("QM",task,r,0);post();ArgumentCaptor<WmsInventoryBatchDto> c=ArgumentCaptor.forClass(WmsInventoryBatchDto.class);verify(inventory).addInventory(c.capture(),eq("QM"));assertEquals(0,c.getValue().getWmsInventoryBatch().getZpActualNumber());assertEquals(5,c.getValue().getWmsInventoryBatch().getCpActualNumber());}
    @Test void zeroFinalReceiptMayClosePreviouslyCompleteIntermediateQuantity(){service.accept("QM",task,receipt("M1",5,false),0);post();assertEquals("PARTIAL",service.detail("QM",1).get("receipt_state"));service.accept("QM",task,receipt("M2",0,true),0);post();assertEquals("COMPLETED",service.detail("QM",1).get("receipt_state"));verify(inventory,times(1)).addInventory(any(),anyString());}
    Map<String,Object> connection(){return map("provider","QIMEN","api_version","2.0","endpoint","https://example.invalid/router","app_key","app","customer_id","customer");}
    Map<String,String> params(String body){Map<String,String> p=new TreeMap<>();p.put("method","taobao.qimen.returnorder.confirm");p.put("v","2.0");p.put("sign_method","md5");p.put("app_key","app");p.put("customerId","customer");p.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));p.put("sign",QimenProtocol.sign(p,body,"fixture"));return p;}
    String xml(){return "<request><returnOrder><returnOrderCode>THX_TEST</returnOrderCode><returnOrderId>WH_RETURN</returnOrderId><warehouseCode>EXT-W</warehouseCode><ownerCode>EXT-O</ownerCode><outBizCode>M1</outBizCode><orderType>HHRK</orderType><confirmType>0</confirmType></returnOrder><orderLines><orderLine><itemCode>A</itemCode><actualQty>5</actualQty><inventoryType>CC</inventoryType><batchCode>RET-BATCH</batchCode></orderLine></orderLines></request>";}
    @Test void officialReturnCallbackUsesItsOwnSignatureAndHeader(){String body=xml();WmsProtocol.Receipt r=protocol.callback(connection(),"fixture",params(body),body);assertEquals("THX_TEST",r.ticketSn);assertTrue(r.complete);assertEquals(5,r.lines.get(0).bad);}
    @Test void changedSignedBodyIsRejected(){String body=xml();assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"fixture",params(body),body.replace("<actualQty>5","<actualQty>6")));}
    @Test void externalEntitiesAreRejectedBeforeAnyStockChange(){String body="<!DOCTYPE foo [<!ENTITY xxe SYSTEM 'file:///etc/passwd'>]>"+xml();assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"fixture",params(body),body));}
    @Test void returnCreateKeepsZeroSecondsInWarehouseTimestamp(){Map<String,Object> input=new LinkedHashMap<>(task);input.put("create_time",LocalDateTime.of(2026,10,17,12,30));assertTrue(protocol.request(connection(),"fixture","CREATE",input).body.contains("<orderCreateTime>2026-10-17 12:30:00</orderCreateTime>"));}
    @Test void returnCreateUsesDedicatedApiAndOriginalShipment(){Map<String,Object> input=new LinkedHashMap<>(task);WmsProtocol.Wire wire=protocol.request(connection(),"fixture","CREATE",input);assertTrue(wire.url.contains("returnorder.create"));assertTrue(wire.body.contains("<orderType>HHRK</orderType>"));assertTrue(wire.body.contains("<preDeliveryOrderCode>XS_TEST</preDeliveryOrderCode>"));assertFalse(wire.body.contains("CGRK"));}

    Map<String,Object> version(){return map("document_version",db.one("SELECT control_version FROM wms_exchange_return WHERE id=?",task.get("id")).get("control_version"),"mode","WITHDRAW","reason","verified cancellation","actor","tester");}
    @Test void neverSentReturnCanBeWithdrawnLocallyWithoutInventoryMutation(){service.documentAction("QM",1,id(task.get("id")),"cancel",version());Map<String,Object> t=db.one("SELECT * FROM wms_exchange_return WHERE id=?",task.get("id"));assertEquals("CONFIRMED",t.get("cancel_state"));assertEquals(5,id(t.get("cancelled_quantity")));verifyNoInteractions(inventory);}
    @Test void cancellationCannotPassUnpostedAcceptedReceipt(){service.accept("QM",task,receipt("PART",2,false),0);assertThrows(IllegalArgumentException.class,()->ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id"))));assertEquals("NONE",db.one("SELECT * FROM wms_exchange_return WHERE id=?",task.get("id")).get("cancel_state"));}
    @Test void partialCancellationPreservesReceivedStockAndRecordsOnlyRemainder(){service.accept("QM",task,receipt("PART",2,false),0);post();ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));post();Map<String,Object> t=db.one("SELECT * FROM wms_exchange_return WHERE id=?",task.get("id"));assertEquals(2,id(t.get("posted_quantity")));assertEquals(3,id(t.get("cancelled_quantity")));assertEquals("CANCELED",t.get("dispatch_state"));assertEquals("PARTIAL",service.detail("QM",1).get("receipt_state"));verify(inventory,times(1)).addInventory(any(),anyString());}
    @Test void lateReceiptIsDurablePendingReviewAndDoesNotIncreaseStock(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));WmsProtocol.Receipt late=receipt("LATE",2,false);service.accept("QM",task,late,0);service.accept("QM",task,late,0);post();assertEquals(1L,jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return_review",Long.class));assertEquals(0L,jdbc.queryForObject("SELECT accepted_quantity FROM wms_exchange_return",Long.class));assertEquals(1,id(service.detail("QM",1).get("pending_review_count")));verifyNoInteractions(inventory);}
    @Test void manuallyConfirmedLateReceiptPostsOnceAndKeepsCancellationBaseline(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));service.accept("QM",task,receipt("LATE",2,false),0);long review=jdbc.queryForObject("SELECT id FROM wms_exchange_return_review",Long.class);service.documentAction("QM",1,id(task.get("id")),"review",map("review_id",review,"decision","ACCEPT","actor","tester","reason","warehouse evidence verified","evidence","case-001"));service.accept("QM",task,receipt("LATE",2,false),0);post();assertEquals(2,id(service.detail("QM",1).get("posted_quantity")));assertEquals(5L,jdbc.queryForObject("SELECT cancelled_quantity FROM wms_exchange_return",Long.class));assertEquals("CANCELED",jdbc.queryForObject("SELECT dispatch_state FROM wms_exchange_return",String.class));verify(inventory,times(1)).addInventory(any(),anyString());}
    @Test void rejectedLateReceiptDoesNotReappearOrPostWhenWarehouseRepeatsIt(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));WmsProtocol.Receipt r=receipt("LATE",2,false);service.accept("QM",task,r,0);long review=jdbc.queryForObject("SELECT id FROM wms_exchange_return_review",Long.class);service.documentAction("QM",1,id(task.get("id")),"review",map("review_id",review,"decision","REJECT","actor","tester","reason","not physical receipt","evidence","case-002"));service.accept("QM",task,r,0);post();assertEquals(0,id(service.detail("QM",1).get("pending_review_count")));assertEquals(0L,jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return_line",Long.class));verifyNoInteractions(inventory);}
    @Test void lateReceiptCannotCompeteWithNewActiveReturnArrangement(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));service.accept("QM",task,receipt("LATE",2,false),0);long review=jdbc.queryForObject("SELECT id FROM wms_exchange_return_review",Long.class);jdbc.update("INSERT INTO wms_exchange_return(company_code,exchange_id,generation,return_sn,exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash) SELECT company_code,exchange_id,2,'THX_NEXT',exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash FROM wms_exchange_return WHERE id=?",task.get("id"));assertThrows(IllegalArgumentException.class,()->service.documentAction("QM",1,id(task.get("id")),"review",map("review_id",review,"decision","ACCEPT","actor","tester","reason","verified","evidence","case-003")));assertEquals(0L,jdbc.queryForObject("SELECT SUM(posted_quantity) FROM wms_exchange_return",Long.class));verifyNoInteractions(inventory);}
    @Test void cancellationCannotUseOtherCompanyOrOtherExchangeDocument(){assertThrows(Exception.class,()->service.documentAction("OTHER",1,id(task.get("id")),"cancel",version()));assertThrows(IllegalArgumentException.class,()->service.documentAction("QM",2,id(task.get("id")),"cancel",version()));assertEquals("NONE",jdbc.queryForObject("SELECT cancel_state FROM wms_exchange_return",String.class));}
    @Test void returnCancellationUsesGenericQimenCancellationWithExchangeInboundType(){Map<String,Object> t=new LinkedHashMap<>(task);t.put("cancel_reason","stop remaining");WmsProtocol.Wire wire=protocol.request(connection(),"fixture","CANCEL",t);assertTrue(wire.url.contains("taobao.qimen.order.cancel"));assertTrue(wire.body.contains("<orderType>HHRK</orderType>"));assertTrue(wire.body.contains("<orderCode>THX_TEST</orderCode>"));assertFalse(wire.body.contains("CGRK"));}

    @Test void neverSentNewArrangementCanBeWithdrawnWhileOldLateReceiptRemainsQuarantined(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));service.accept("QM",task,receipt("LATE",2,false),0);jdbc.update("INSERT INTO wms_exchange_return(company_code,exchange_id,generation,return_sn,exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash) SELECT company_code,exchange_id,2,'THX_NEXT',exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash FROM wms_exchange_return WHERE id=?",task.get("id"));long next=jdbc.queryForObject("SELECT id FROM wms_exchange_return WHERE generation=2",Long.class);service.documentAction("QM",1,next,"cancel",map("document_version",1,"mode","WITHDRAW","reason","withdraw unsent only","actor","tester"));assertEquals("CONFIRMED",jdbc.queryForObject("SELECT cancel_state FROM wms_exchange_return WHERE id=?",String.class,next));assertEquals(1,id(service.detail("QM",1).get("pending_review_count")));assertEquals(0L,jdbc.queryForObject("SELECT SUM(posted_quantity) FROM wms_exchange_return",Long.class));verifyNoInteractions(inventory);}
    @Test void warehouseCancellationStillBlocksWhenAnotherReturnHasUnreviewedLateReceipt(){ReflectionTestUtils.invokeMethod(service,"confirmCancel","QM",id(task.get("id")));service.accept("QM",task,receipt("LATE",2,false),0);jdbc.update("INSERT INTO wms_exchange_return(company_code,exchange_id,generation,return_sn,exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash,attempts,dispatch_state,external_order) SELECT company_code,exchange_id,2,'THX_NEXT',exchange_sn,order_sn,platform_tid,original_shipment_sn,store_code,sku_sn,quantity,connection_id,external_warehouse,external_owner,real_store_code,owner_code,payload_hash,1,'ACCEPTED','WH_NEXT' FROM wms_exchange_return WHERE id=?",task.get("id"));long next=jdbc.queryForObject("SELECT id FROM wms_exchange_return WHERE generation=2",Long.class);assertThrows(IllegalArgumentException.class,()->service.documentAction("QM",1,next,"cancel",map("document_version",1,"mode","WITHDRAW","reason","requires review first","actor","tester")));assertEquals("NONE",jdbc.queryForObject("SELECT cancel_state FROM wms_exchange_return WHERE id=?",String.class,next));verifyNoInteractions(inventory);}
}
